import{_ as o,o as e,c as a,ag as n}from"./chunks/framework.DQQHyi2x.js";const u=JSON.parse('{"title":"Hooks","description":"","frontmatter":{},"headers":[],"relativePath":"features/hooks.md","filePath":"features/hooks.md"}'),r={name:"features/hooks.md"};function s(i,t,d,l,c,h){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="hooks" tabindex="-1">Hooks <a class="header-anchor" href="#hooks" aria-label="Permalink to &quot;Hooks&quot;">​</a></h1><p>Configure event-triggered actions that run during the Claude Code lifecycle.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Hooks execute commands, inject prompts, or spawn subagents in response to Claude Code events. They&#39;re stored in <code>settings.json</code> and organized by event type.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="browsing-hooks" tabindex="-1">Browsing Hooks <a class="header-anchor" href="#browsing-hooks" aria-label="Permalink to &quot;Browsing Hooks&quot;">​</a></h3><p>The Hooks page shows hooks organized in tabs by event type. Stats cards at the top show total, user, and project hook counts.</p><h3 id="creating-a-hook" tabindex="-1">Creating a Hook <a class="header-anchor" href="#creating-a-hook" aria-label="Permalink to &quot;Creating a Hook&quot;">​</a></h3><p>Click <strong>&quot;Add Hook&quot;</strong> to open the wizard:</p><ol><li><strong>Event</strong> — select when the hook triggers (see events table below)</li><li><strong>Matcher</strong> — optional pattern to filter which tools trigger the hook</li><li><strong>Type &amp; Content</strong> — choose the hook type and configure it: <ul><li><strong>Command</strong> — shell command to execute</li><li><strong>Prompt</strong> — text to inject into the conversation</li><li><strong>Agent</strong> — spawn a subagent with a prompt and model selection</li></ul></li><li><strong>Scope &amp; Options</strong> — set user/project scope and advanced options</li></ol><h3 id="hook-events" tabindex="-1">Hook Events <a class="header-anchor" href="#hook-events" aria-label="Permalink to &quot;Hook Events&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Event</th><th>When It Fires</th></tr></thead><tbody><tr><td><code>PreToolUse</code></td><td>Before a tool is called</td></tr><tr><td><code>PostToolUse</code></td><td>After a tool completes</td></tr><tr><td><code>BeforeCompletion</code></td><td>Before Claude sends a response</td></tr><tr><td><code>Notification</code></td><td>When a notification is displayed</td></tr><tr><td><code>Stop</code></td><td>When Claude stops generating</td></tr><tr><td><code>SubagentStop</code></td><td>When a subagent stops</td></tr><tr><td><code>PreCompact</code></td><td>Before context compaction</td></tr><tr><td><code>PostCompact</code></td><td>After context compaction</td></tr><tr><td><code>UserPromptSubmit</code></td><td>When the user submits a prompt</td></tr></tbody></table><h3 id="hook-types" tabindex="-1">Hook Types <a class="header-anchor" href="#hook-types" aria-label="Permalink to &quot;Hook Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Description</th><th>Example</th></tr></thead><tbody><tr><td><strong>Command</strong></td><td>Execute a shell command</td><td><code>npm run lint</code></td></tr><tr><td><strong>Prompt</strong></td><td>Inject text into the conversation</td><td>&quot;Remember to follow the style guide&quot;</td></tr><tr><td><strong>Agent</strong></td><td>Spawn a Claude subagent</td><td>Custom review agent with Haiku model</td></tr></tbody></table><h3 id="advanced-options" tabindex="-1">Advanced Options <a class="header-anchor" href="#advanced-options" aria-label="Permalink to &quot;Advanced Options&quot;">​</a></h3><ul><li><strong>Matcher</strong> — regex/glob pattern to match specific tools (e.g., <code>Bash</code> to only trigger on Bash tool use)</li><li><strong>Async</strong> — run in the background without blocking Claude</li><li><strong>Once</strong> — run only once per session</li><li><strong>Status Message</strong> — custom spinner text while the hook executes</li><li><strong>Timeout</strong> — maximum execution time in seconds</li></ul><h3 id="environment-variables" tabindex="-1">Environment Variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment Variables&quot;">​</a></h3><p>Command hooks have access to context variables:</p><ul><li><code>$CLAUDE_TOOL_NAME</code> — name of the tool being used</li><li><code>$CLAUDE_TOOL_ARGS</code> — tool arguments as JSON</li><li><code>$CLAUDE_PROJECT_DIR</code> — current project directory</li></ul><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>Hooks are stored in <code>settings.json</code> under the <code>hooks</code> key, organized by event:</p><table tabindex="0"><thead><tr><th>File</th><th>Scope</th></tr></thead><tbody><tr><td><code>~/.claude/settings.json</code></td><td>User hooks</td></tr><tr><td><code>.claude/settings.json</code></td><td>Project hooks</td></tr></tbody></table><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><ul><li>Use <strong>PreToolUse</strong> hooks for validation (e.g., lint before committing).</li><li>Use <strong>PostToolUse</strong> hooks for logging or notifications.</li><li><strong>Prompt hooks</strong> on <code>BeforeCompletion</code> can enforce coding standards.</li><li>The <strong>async</strong> flag is useful for long-running operations that shouldn&#39;t block Claude.</li><li><strong>Templates</strong> in the wizard provide quick starts for common hook patterns.</li></ul>',24)])])}const p=o(r,[["render",s]]);export{u as __pageData,p as default};
